"""Automatically generated scenario tests for gatk_sv_gd.integrate.

Generated by ``scratch/convert_scenarios_to_pytest.py`` from 98
scenario JSON files in ``tests/data/scenarios/``.

Each scenario represents a structured edge-case for the VCF integration
pipeline.  Tests are grouped into logical subclasses by theme.

To run all scenario tests::

    pytest tests/test_scenarios.py -v

To run only integration-marked tests::

    pytest tests/test_scenarios.py -m integration

"""


import pytest

from gatk_sv_gd import integrate

from test_integrate import (
    _FakeRecord,
    _FakeHeader,
    _run_integrate_main,
    FakeIntervalTree,
)



class TestGenotypeReconciliation:
    """Tests for GenotypeReconciliation scenarios."""
    @pytest.mark.integration
    def test_scenario_006_all_homref_after_reconciliation(self, monkeypatch, tmp_path):
        """Scenario 6: all_homref_after_reconciliation."""
        # A VCF record has all hom-ref samples (0,0). GD entry has carriers listed. After reconciliation, all samples become hom-ref → record must be SKIPPED.

        vcf_records = [
            _FakeRecord(
                chrom="chr1",
                pos=1001,
                stop=5001,
                record_id="var1",
                alts=['<DEL>'],
                info={'SVTYPE': 'DEL'},
                samples={
                "S1": {"GT": [0, 0]},
                "S2": {"GT": [0, 0]}
                },
            )
        ]
        vcf_header = _FakeHeader(
            contigs={'chr1': None},
            samples=['S1', 'S2'],
        )
        gd_table_rows = [
            {"chr": 'chr1', "start": 1000, "end": 5000, "gd_id": 'GD1', "svtype": 'DEL', "nahr": 'yes', "cluster": 'clusterA', "bp1": '1', "bp2": '2'}
        ]
        gd_calls_entries = [
            {"chrom": 'chr1', "pos": 1000, "end": 5000, "region_id": 'GD1', "svtype": 'DEL', "samples": []}
        ]
        samples_ploidy = None
        par_intervals = None
        extra_argv = None

        written = _run_integrate_main(
            monkeypatch, tmp_path,
            vcf_records=vcf_records,
            vcf_header=vcf_header,
            gd_table_rows=gd_table_rows,
            gd_calls_entries=gd_calls_entries,
            samples_ploidy=samples_ploidy,
            par_intervals=par_intervals,
            extra_argv=extra_argv,
        )

        assert len(written) == 0
    @pytest.mark.integration
    def test_scenario_020_genotype_reconciliation_cascade(self, monkeypatch, tmp_path):
        """Scenario 20: genotype_reconciliation_cascade."""
        # VCF record has mixed genotypes: S1=het(0,1), S2=hom-ref(0,0), S3=no-call(None,None). GD entry has carriers S1 and S2. S2 should become het; S3 (no carrier) stays hom-ref; S1 stays het. At least one carrier remains → record written.

        vcf_records = [
            _FakeRecord(
                chrom="chr1",
                pos=1001,
                stop=5001,
                record_id="var1",
                alts=['<DEL>'],
                info={'SVTYPE': 'DEL'},
                samples={
                "S1": {"GT": [0, 1], "RD_CN": 1},
                "S2": {"GT": [0, 0], "RD_CN": 2},
                "S3": {"GT": [None, None]}
                },
            )
        ]
        vcf_header = _FakeHeader(
            contigs={'chr1': None},
            samples=['S1', 'S2', 'S3'],
        )
        gd_table_rows = [
            {"chr": 'chr1', "start": 1000, "end": 5000, "gd_id": 'GD1', "svtype": 'DEL', "nahr": 'yes', "cluster": 'clusterA', "bp1": '1', "bp2": '2'}
        ]
        gd_calls_entries = [
            {"chrom": 'chr1', "pos": 1000, "end": 5000, "region_id": 'GD1', "svtype": 'DEL', "samples": ['S1', 'S2']}
        ]
        samples_ploidy = None
        par_intervals = None
        extra_argv = None

        written = _run_integrate_main(
            monkeypatch, tmp_path,
            vcf_records=vcf_records,
            vcf_header=vcf_header,
            gd_table_rows=gd_table_rows,
            gd_calls_entries=gd_calls_entries,
            samples_ploidy=samples_ploidy,
            par_intervals=par_intervals,
            extra_argv=extra_argv,
        )

        assert len(written) == 1
        gd_ids = {r.info.get("GENOMIC_DISORDER") for r in written}
        assert "GD1" in gd_ids
